package com.cpf.core.api.reliability;import java.time.Duration;public record CpfSelfHealingPolicy(int maxActionsPerWindow,int maxConsecutiveFailures,Duration window,Duration cooldown){public CpfSelfHealingPolicy{if(maxActionsPerWindow<1||maxConsecutiveFailures<1)throw new IllegalArgumentException("self-healing limits must be positive");window=window==null?Duration.ofMinutes(10):window;cooldown=cooldown==null?Duration.ofMinutes(5):cooldown;}}